Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "isValid(datum[''Eletricidade: PIS/Cofins'']) || isValid(datum[''Eletricidade: sem tributos''])"
    },
    {
      "calculate": "(isValid(datum[''Eletricidade: sem tributos'']) ? datum[''Eletricidade: sem tributos''] : 0) + (isValid(datum[''Eletricidade: ICMS'']) ? datum[''Eletricidade: ICMS''] : 0) + (isValid(datum[''Eletricidade: PIS/Cofins'']) ? datum[''Eletricidade: PIS/Cofins''] : 0)",
      "as": "total"
    },
    {
      "filter": "datum.total > 0"
    },
    {
      "calculate": "format(datum.total, ''$,.2f'')",
      "as": "Total por 100 km"
    },
    {
      "calculate": "format(datum[''Eletricidade: sem tributos''], ''$,.2f'')",
      "as": "Tarifa + bandeira"
    },
    {
      "calculate": "format(datum[''Eletricidade: ICMS''], ''$,.2f'') + '' ('' + format(datum[''Eletricidade: ICMS''] / datum.total, ''.0%'') + '')''",
      "as": "ICMS"
    },
    {
      "calculate": "format(datum[''Eletricidade: PIS/Cofins''], ''$,.2f'') + '' ('' + format(datum[''Eletricidade: PIS/Cofins''] / datum.total, ''.0%'') + '')''",
      "as": "PIS/Cofins"
    },
    {
      "calculate": "format((datum[''Eletricidade: ICMS''] + datum[''Eletricidade: PIS/Cofins'']) / datum.total, ''.0%'')",
      "as": "Tributos no total"
    },
    {
      "fold": [
        "Eletricidade: sem tributos",
        "Eletricidade: ICMS",
        "Eletricidade: PIS/Cofins"
      ],
      "as": [
        "serie",
        "valor"
      ]
    },
    {
      "calculate": "isValid(datum.valor) ? datum.valor : 0",
      "as": "valor"
    },
    {
      "calculate": "datum.serie == ''Eletricidade: sem tributos'' ? ''Sem tributos (tarifa + bandeira)'' : datum.serie == ''Eletricidade: ICMS'' ? ''ICMS'' : datum.serie == ''Eletricidade: PIS/Cofins'' ? ''PIS/Cofins'' : ''''",
      "as": "Parcela"
    },
    {
      "calculate": "datum.serie == ''Eletricidade: sem tributos'' ? 0 : datum.serie == ''Eletricidade: ICMS'' ? 1 : datum.serie == ''Eletricidade: PIS/Cofins'' ? 2 : 9",
      "as": "ordem"
    }
  ],
  "mark": {
    "type": "area",
    "interpolate": "step-after"
  },
  "encoding": {
    "x": {
      "field": "Mês",
      "type": "temporal",
      "timeUnit": "yearmonth",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "labelAlign": "left",
        "labelPadding": 6,
        "labelOverlap": "greedy"
      }
    },
    "y": {
      "field": "valor",
      "type": "quantitative",
      "stack": "zero",
      "title": "R$ por 100 km",
      "axis": {
        "format": "$,.0f",
        "tickCount": 5
      }
    },
    "color": {
      "field": "Parcela",
      "type": "nominal",
      "scale": {
        "domain": [
          "Sem tributos (tarifa + bandeira)",
          "ICMS",
          "PIS/Cofins"
        ],
        "range": [
          "#E1DFDD",
          "#F2C811",
          "#605E5C"
        ]
      },
      "legend": {
        "orient": "top",
        "title": null,
        "direction": "horizontal",
        "columns": 3,
        "labelLimit": 220
      }
    },
    "order": {
      "field": "ordem",
      "type": "quantitative"
    },
    "tooltip": [
      {
        "field": "Mês",
        "type": "temporal",
        "timeUnit": "yearmonth",
        "title": "Mês",
        "format": "%b/%Y"
      },
      {
        "field": "Total por 100 km"
      },
      {
        "field": "Tarifa + bandeira"
      },
      {
        "field": "ICMS"
      },
      {
        "field": "PIS/Cofins"
      },
      {
        "field": "Tributos no total"
      }
    ]
  }
}'
